import timefrom selenium import webdriverfrom selenium.webdriver.common.by import Bydef test_webpage_task():    #Launch browser    driver = webdriver.Chrome()    #Open URL    driver.get("https://www.saucedemo.com/")    #Get Title    title = driver.title    print("Title: ", title)    #Get CurrentURL    current_url = driver.current_url    print("Current URL: ", current_url)    #Get Page Source Entire Content    file = open("../webpage_task_11.txt", "w", encoding="utf-8")    file.write(driver.page_source)    file.close()    print("Page source saved")    #Login    driver.find_element(By.ID, "user-name").send_keys("standard_user")    driver.find_element(By.ID, "password").send_keys("secret_sauce")    driver.find_element(By.CSS_SELECTOR, "input[type = 'submit']").click()    time.sleep(5)    #After Login DashboardURL    dasboardURL_Afterexec = driver.title    print("dasboardURL_AfterExec: ", dasboardURL_Afterexec)    #Close Browser    driver.quit()